begin;
select no_plan();
select has_function('public','acquire_automatic_banking_sync',array['uuid','uuid'],'automatic admission exists');
insert into auth.users(id) values ('10000000-0000-4000-8000-000000000001');
insert into public.app_settings(owner_user_id) values ('10000000-0000-4000-8000-000000000001');
select is(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001',gen_random_uuid()),null::jsonb,'missing integration skips');
insert into public.integrations(owner_user_id,provider) values ('10000000-0000-4000-8000-000000000001','qonto');
select is(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001',gen_random_uuid()),null::jsonb,'first publication remains manual');
update public.integrations set last_success_at=clock_timestamp()-interval '4 minutes 59 seconds';
select is(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001',gen_random_uuid()),null::jsonb,'under five minutes skips');
update public.integrations set last_success_at=clock_timestamp()+interval '1 day';
select is(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001',gen_random_uuid()),null::jsonb,'future publication skips');
select is((select count(*) from public.sync_runs),0::bigint,'skips create no runs');
update public.integrations set last_success_at=clock_timestamp()-interval '5 minutes';
select isnt(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001'),null::jsonb,'five minutes admits');
select ok((select last_auto_attempt_at is not null and isfinite(last_auto_attempt_at) from public.integrations),'admitted attempt stamped');
select public.fail_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','PROVIDER_UNAVAILABLE',false);
update public.integrations set last_success_at=clock_timestamp()-interval '1 hour', last_auto_attempt_at=clock_timestamp()-interval '14 minutes 59 seconds';
select is(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001',gen_random_uuid()),null::jsonb,'cooldown before 15 minutes skips');
update public.integrations set last_auto_attempt_at=clock_timestamp()-interval '15 minutes';
select isnt(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002'),null::jsonb,'15 minute cooldown admits');
select public.fail_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','PROVIDER_UNAVAILABLE',false);
update public.integrations set last_auto_attempt_at=null;
select public.acquire_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003');
select is(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001',gen_random_uuid()),null::jsonb,'manual live lease skips neutrally');
select is((select last_auto_attempt_at from public.integrations),null::timestamptz,'skip does not stamp attempt');
select throws_ok($$select public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000009',gen_random_uuid())$$,'42501','DATABASE_ERROR','invalid owner rejected');
select throws_ok($$update public.integrations set last_auto_attempt_at='infinity'$$,'23514',null,'infinite attempt prohibited');
select ok(not has_function_privilege(r,'public.acquire_automatic_banking_sync(uuid,uuid)','EXECUTE'),r||' cannot acquire automatically') from unnest(array['anon','authenticated']) r;
select ok(has_function_privilege('service_role','public.acquire_automatic_banking_sync(uuid,uuid)','EXECUTE'),'service role may acquire');
select public.fail_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000003','PROVIDER_UNAVAILABLE',false);
update public.integrations set last_success_at=clock_timestamp()-interval '6 minutes', last_auto_attempt_at=clock_timestamp()-interval '7 minutes';
select isnt(public.acquire_automatic_banking_sync('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000004'),null::jsonb,'successful automatic publication does not impose fifteen minute cooldown');
select * from finish();
rollback;
